// Client code to handle version deprecation
async function callAPI(endpoint, options = {}) {
  const response = await fetch(`/v1${endpoint}`, options);

  // Check for deprecation warnings
  const warning = response.headers.get('Warning');
  const sunset = response.headers.get('Sunset');

  if (warning) {
    console.warn(`API Deprecation: ${warning}`);

    // Log to monitoring
    logDeprecation({
      endpoint,
      warning,
      sunset
    });

    // If sunset is approaching, alert
    if (sunset && new Date(sunset) < new Date(Date.now() + 30 * 86400000)) {
      console.error('⚠️ This API version will be retired soon!');
    }
  }

  return response.json();
}

