# hipaa_audit.py
import logging
import json
from datetime import datetime
from functools import wraps

class HIPAAAuditLogger:
    def __init__(self):
        self.logger = logging.getLogger('hipaa_audit')
        handler = logging.FileHandler('hipaa_audit.log')
        handler.setFormatter(logging.Formatter('%(asctime)s - %(message)s'))
        self.logger.addHandler(handler)
        self.logger.setLevel(logging.INFO)

    def log_access(self, user_id, accessed_by, resource, action):
        """Log access to PHI for HIPAA compliance"""
        entry = {
            'timestamp': datetime.utcnow().isoformat(),
            'user_id': user_id,
            'accessed_by': accessed_by,
            'resource': resource,
            'action': action,
            'ip_address': request.remote_addr,
            'user_agent': request.user_agent.string,
            'reason': request.headers.get('X-Access-Reason', 'clinical')
        }
        self.logger.info(json.dumps(entry))

    def audit_decorator(self, resource_name):
        """Decorator to automatically log access to PHI"""
        def decorator(f):
            @wraps(f)
            def wrapped(*args, **kwargs):
                # Log access before processing
                user_id = kwargs.get('user_id') or kwargs.get('patient_id')
                if user_id:
                    self.log_access(
                        user_id=user_id,
                        accessed_by=request.headers.get('X-User-ID'),
                        resource=resource_name,
                        action=request.method
                    )
                return f(*args, **kwargs)
            return wrapped
        return decorator

# Initialize once
hipaa_logger = HIPAAAuditLogger()

# Usage in routes
@app.route('/api/phi/patients/<patient_id>/records')
@hipaa_logger.audit_decorator('medical_records')
def get_patient_records(patient_id):
    # This endpoint accesses PHI - automatically logged
    return get_medical_records(patient_id)

# pci_compliance.py
import re
import hashlib
import hmac

class PCICompliance:
    """PCI-DSS compliant payment data handling"""

    @staticmethod
    def validate_pan(pan):
        """Validate Primary Account Number (Luhn algorithm)"""
        # Remove non-digits
        pan = re.sub(r'\D', '', pan)

        # Check length (typically 16)
        if len(pan) < 12 or len(pan) > 19:
            return False

        # Luhn algorithm
        total = 0
        reverse = pan[::-1]
        for i, digit in enumerate(reverse):
            n = int(digit)
            if i % 2 == 1:
                n *= 2
                if n > 9:
                    n -= 9
            total += n

        return total % 10 == 0

    @staticmethod
    def mask_pan(pan):
        """Mask PAN for display (PCI requirement: show only last 4)"""
        pan = re.sub(r'\D', '', pan)
        if len(pan) >= 4:
            return '*' * (len(pan) - 4) + pan[-4:]
        return pan

    @staticmethod
    def encrypt_pan(pan, key):
        """Encrypt PAN for storage (PCI requirement: encryption at rest)"""
        from cryptography.fernet import Fernet
        f = Fernet(key)
        return f.encrypt(pan.encode()).decode()

    @staticmethod
    def hash_pan_for_indexing(pan, salt):
        """Create searchable hash (PCI: don't index encrypted PAN)"""
        return hmac.new(
            salt.encode(),
            pan.encode(),
            hashlib.sha256
        ).hexdigest()

# Payment processing endpoint
@app.route('/api/payments', methods=['POST'])
def process_payment():
    data = request.json
    pan = data.get('pan')

    # PCI Requirement 3: Protect stored cardholder data
    if not PCICompliance.validate_pan(pan):
        return jsonify({'error': 'INVALID_PAN'}), 400

    # PCI Requirement 3.3: Mask PAN when displayed
    log_data = {
        'masked_pan': PCICompliance.mask_pan(pan),
        'amount': data.get('amount'),
        'timestamp': datetime.utcnow().isoformat()
    }
    app.logger.info(f"Payment processed: {log_data}")

    # PCI Requirement 3.4: Render PAN unreadable (encryption)
    encrypted_pan = PCICompliance.encrypt_pan(pan, app.config['ENCRYPTION_KEY'])
    pan_hash = PCICompliance.hash_pan_for_indexing(pan, app.config['HASH_SALT'])

    # Store only encrypted PAN and hash
    store_payment({
        'encrypted_pan': encrypted_pan,
        'pan_hash': pan_hash,
        'amount': data.get('amount'),
        'status': 'processed'
    })

    # PCI Requirement 3.2: Do not store CVV
    # CVV is never stored, only passed to processor

    return jsonify({'status': 'success'}), 200

