    def test_webhook_idempotency(self):
        """Test that duplicate webhooks are handled idempotently"""
        api_key = "test-idempotent-key"

        webhook_payload = {
            'event': 'invoice.payment_succeeded',
            'data': {
                'customer': 'cus_123',
                'subscription': 'sub_456',
                'amount': 9900,
                'period_end': int(time.time()) + 30*24*3600
            },
            'idempotency_key': 'unique-123'  # Prevent duplicates
        }

        signature = hmac.new(
            key=b'webhook_secret',
            msg=json.dumps(webhook_payload).encode(),
            digestmod=hashlib.sha256
        ).hexdigest()

        # Send twice
        for _ in range(2):
            response = requests.post(
                f"{BASE_URL}/billing/webhook",
                json=webhook_payload,
                headers={
                    'X-Signature': signature,
                    'X-API-Key': api_key
                }
