        # Should only have been processed once
        # Check audit log for duplicate events
        audit = requests.get(f"{BASE_URL}/audit", headers={"X-API-Key": api_key}).json()
        payment_events = [e for e in audit if e['type'] == 'payment_succeeded']
        assert len(payment_events) == 1

