import pytest
import requests
import uuid
import time
from concurrent.futures import ThreadPoolExecutor

class TestIdempotency:
    BASE_URL = "https://api.payflow.example/v1"
    API_KEY = "test-key-123"

    def test_idempotent_payment(self):
        """Same idempotency key returns same response without double-charging"""
        idempotency_key = str(uuid.uuid4())

        payment_data = {
            "amount": 1000,  # $10.00
            "currency": "USD",
            "paymentMethod": {
                "type": "card",
                "card": {
                    "number": "4111111111111111",
                    "expiryMonth": 12,
                    "expiryYear": 2026,
                    "cvv": "123"
                }
            },
            "idempotencyKey": idempotency_key
        }

        # First request
        response1 = requests.post(
            f"{self.BASE_URL}/payments",
            json=payment_data,
            headers={"X-API-Key": self.API_KEY}
        )
        assert response1.status_code == 200
        data1 = response1.json()
        payment_id = data1['id']

        # Wait a bit
        time.sleep(0.5)

        # Duplicate request with same idempotency key
        response2 = requests.post(
            f"{self.BASE_URL}/payments",
            json=payment_data,
            headers={"X-API-Key": self.API_KEY}
        )
        assert response2.status_code == 200
        data2 = response2.json()

        # Should return same payment ID
        assert data2['id'] == payment_id

        # Verify only one transaction in database
        transactions = self.get_transactions(payment_id)
        assert len(transactions) == 1

    def test_different_idempotency_keys_different_payments(self):
        """Different keys create different payments even with same data"""
        payment_data = {
            "amount": 1000,
            "currency": "USD",
            "paymentMethod": {
                "type": "card",
                "card": {
                    "number": "4111111111111111",
                    "expiryMonth": 12,
                    "expiryYear": 2026,
                    "cvv": "123"
                }
            }
