# Example of a service that integrates with multiple third-party APIs

class PaymentService:
    def __init__(self):
        self.stripe_client = StripeClient(api_key=config.STRIPE_KEY)
        self.paypal_client = PaypalClient(api_key=config.PAYPAL_KEY)
        self.circuit_breaker = CircuitBreaker(failure_threshold=5, timeout=60)
        self.cache = TTLCache(maxsize=100, ttl=300)  # 5 minute cache

    def process_payment(self, amount, currency, method):
        """Process payment with fallback between providers"""

        # Try primary provider (Stripe) with circuit breaker
        if self.circuit_breaker.allow_request():
            try:
                result = self.stripe_client.charge(amount, currency, method)
                return result
            except StripeAPIError as e:
                self.circuit_breaker.record_failure()
                # Fallback to PayPal
                return self.paypal_client.charge(amount, currency, method)
            except Exception as e:
                self.circuit_breaker.record_failure()
                raise
        else:
            # Circuit open, try fallback directly
            return self.paypal_client.charge(amount, currency, method)

class GeoService:
    def __init__(self):
        self.google_maps = GoogleMapsClient(api_key=config.GOOGLE_MAPS_KEY)
        self.openstreetmap = OpenStreetMapClient()  # Free fallback
        self.rate_limiter = RateLimiter(max_calls=50, period=60)  # 50 per minute

    def geocode_address(self, address):
        """Geocode with rate limiting and fallback"""

        # Check cache first
        cache_key = f"geocode:{address}"
        if cache_key in cache:
            return cache[cache_key]

        # Apply rate limiting
        if not self.rate_limiter.allow():
            # Use fallback (maybe less accurate but free)
            result = self.openstreetmap.geocode(address)
            cache[cache_key] = result
            return result

        # Try primary with timeout
        try:
            result = self.google_maps.geocode(address, timeout=2)
            cache[cache_key] = result
            return result
        except GoogleMapsError:
            # Fallback on error
            result = self.openstreetmap.geocode(address)
            cache[cache_key] = result
            return result
        except TimeoutError:
            # Fallback on timeout
            result = self.openstreetmap.geocode(address)
            cache[cache_key] = result
            return result

class EmailService:
    def __init__(self):
        self.sendgrid = SendGridClient(api_key=config.SENDGRID_KEY)
        self.ses = AWS_SES_Client(api_key=config.AWS_KEY)
        self.queue = []  # Retry queue

    def send_email(self, to, subject, body):
        """Send email with retry queue and multiple providers"""

        # Try primary
        try:
            return self.sendgrid.send(to, subject, body)
        except SendGridRateLimitError:
            # Rate limited, queue for retry
            self.queue.append({
                'to': to, 'subject': subject, 'body': body,
                'retry_count': 0, 'next_retry': time.time() + 60
            })
            return {'status': 'queued'}
        except SendGridError:
            # Try fallback
            try:
                return self.ses.send(to, subject, body)
            except SESError:
                # Both failed, queue for retry
                self.queue.append({
                    'to': to, 'subject': subject, 'body': body,
                    'retry_count': 0, 'next_retry': time.time() + 300
                })
                return {'status': 'queued'}

