            response = requests.post(
                f"{BASE_URL}/webhooks/stripe",
                json=payload,
                headers=headers
            )

            assert response.status_code == expected_status

    def test_webhook_replay_protection(self):
        """Test protection against replay attacks"""
        payload = {
            'id': 'evt_123456',
            'type': 'payment.succeeded',
            'timestamp': int(time.time()) - 3600  # 1 hour old
        }

        headers = {'X-Signature': create_webhook_signature(payload)}

        # Old webhook should be rejected
        response = requests.post(
            f"{BASE_URL}/webhooks/stripe",
            json=payload,
            headers=headers
        )
        assert response.status_code == 400
        assert 'timestamp' in response.text.lower()

