class ProductionDataAnonymizer:
    """Anonymize production data for test environments"""

    def __init__(self):
        self.masker = DataMasker(seed=42)  # Reproducible masking

        # Define masking rules for different entities
        self.user_rules = {
            'email': 'email',
            'first_name': 'name',
            'last_name': 'name',
            'phone': 'phone',
            'address': 'address',
            'ssn': 'ssn'
        }

        self.payment_rules = {
            'card_number': 'credit_card',
            'cvv': 'token',
            'cardholder_name': 'name'
        }

    def anonymize_user(self, user):
        """Anonymize a user record"""
        return self.masker.mask_record(user, self.user_rules)

    def anonymize_payment(self, payment):
        """Anonymize a payment record"""
        return self.masker.mask_record(payment, self.payment_rules)

    def anonymize_database_export(self, input_file, output_file):
        """Anonymize an entire database export"""
        import json

        with open(input_file, 'r') as f:
            data = json.load(f)

        anonymized = {
            'users': [self.anonymize_user(u) for u in data.get('users', [])],
            'payments': [self.anonymize_payment(p) for p in data.get('payments', [])],
            'orders': data.get('orders', [])  # Orders reference anonymized IDs
        }

        with open(output_file, 'w') as f:
            json.dump(anonymized, f, indent=2)


