import pytest
import redis
import json
from contextlib import contextmanager

class TestDataManager:
    """Manage test data lifecycle"""

    def __init__(self, db_connection, cache=None):
        self.db = db_connection
        self.cache = cache or {}
        self.created_entities = []

    def create_user(self, user_data):
        """Create user and track for cleanup"""
        user_id = self.db.users.insert(user_data)
        self.created_entities.append({
            'type': 'user',
            'id': user_id,
            'cleanup_method': self.delete_user
        })
        return user_id

    def create_order(self, order_data):
        """Create order and track for cleanup"""
        order_id = self.db.orders.insert(order_data)
        self.created_entities.append({
            'type': 'order',
            'id': order_id,
            'cleanup_method': self.delete_order
        })
        return order_id

    def delete_user(self, user_id):
        """Delete user and related data"""
        # Delete user's orders first
        self.db.orders.delete(user_id=user_id)
        # Delete user
        self.db.users.delete(id=user_id)

    def delete_order(self, order_id):
        """Delete order"""
        self.db.orders.delete(id=order_id)

    def cleanup_all(self):
        """Clean up all created entities in reverse order"""
        for entity in reversed(self.created_entities):
            try:
                entity['cleanup_method'](entity['id'])
            except Exception as e:
                print(f"Cleanup failed for {entity['type']} {entity['id']}: {e}")
        self.created_entities.clear()

    @contextmanager
    def transaction(self):
        """Context manager for test data within a transaction"""
        try:
            yield self
        finally:
            self.cleanup_all()


