class DataAnonymizer:
    """Anonymize sensitive data using various techniques"""

    def __init__(self, seed: Optional[int] = None):
        if seed:
            random.seed(seed)
            Faker.seed(seed)

    # ============================================
    # MASKING TECHNIQUES
    # ============================================

    def mask_email(self, email: str, visible_chars: int = 2) -> str:
        """Mask email: j***@example.com"""
        if not email or '@' not in email:
            return email

        local_part, domain = email.split('@')
        if len(local_part) <= visible_chars:
            masked_local = '*' * len(local_part)
        else:
            masked_local = local_part[:visible_chars] + '*' * (len(local_part) - visible_chars)

        return f"{masked_local}@{domain}"

    def mask_phone(self, phone: str, visible_digits: int = 4) -> str:
        """Mask phone: ***-***-1234"""
        # Extract digits
        digits = re.sub(r'\D', '', phone)
        if len(digits) < visible_digits:
            return phone

        # Keep last N digits
        visible = digits[-visible_digits:]
        masked = '*' * (len(digits) - visible_digits) + visible

        # Try to preserve original formatting
        result = ''
        digit_index = 0
        for char in phone:
            if char.isdigit():
                result += masked[digit_index]
                digit_index += 1
            else:
                result += char

        return result

    def mask_name(self, name: str) -> str:
        """Mask name: John S. or J*** S***"""
        parts = name.split()
        masked_parts = []

        for part in parts:
            if len(part) <= 2:
                masked_parts.append(part[0] + '*' * (len(part) - 1))
            else:
                masked_parts.append(part[0] + '*' * (len(part) - 2) + part[-1])

        return ' '.join(masked_parts)

    def mask_credit_card(self, card_number: str) -> str:
        """Mask credit card: ****-****-****-1234"""
        # Extract digits
        digits = re.sub(r'\D', '', card_number)
        if len(digits) < 4:
            return card_number

        # Keep last 4 digits
        visible = digits[-4:]
        masked = '*' * (len(digits) - 4) + visible

        # Try to preserve original formatting
        result = ''
        digit_index = 0
        for char in card_number:
            if char.isdigit():
                result += masked[digit_index]
                digit_index += 1
            else:
                result += char

        return result

    # ============================================
    # SUBSTITUTION TECHNIQUES
    # ============================================

    def substitute_email(self) -> str:
        """Generate fake email"""
        return fake.email()

    def substitute_name(self) -> str:
        """Generate fake name"""
        return fake.name()

    def substitute_phone(self) -> str:
        """Generate fake phone number"""
        return fake.phone_number()

    def substitute_address(self) -> Dict:
        """Generate fake address"""
        return {
            "street": fake.street_address(),
            "city": fake.city(),
            "state": fake.state_abbr(),
            "zip": fake.zipcode(),
            "country": fake.country_code()
        }

    def substitute_company(self) -> str:
        """Generate fake company name"""
        return fake.company()

    # ============================================
    # TOKENIZATION TECHNIQUES
    # ============================================

    def tokenize(self, value: str, namespace: str = "default") -> str:
        """Create deterministic token from value"""
        if not value:
            return value

        # Create consistent hash
        hash_input = f"{namespace}:{value}".encode('utf-8')
        token = hashlib.sha256(hash_input).hexdigest()[:16]
        return f"tok_{token}"

    def tokenize_with_mapping(self, value: str, mapping: Dict[str, str]) -> str:
        """Tokenize using a precomputed mapping (for consistency)"""
        if value in mapping:
            return mapping[value]

        token = self.tokenize(value)
        mapping[value] = token
        return token

    # ============================================
    # GENERALIZATION TECHNIQUES
    # ============================================

    def generalize_date(self, date_str: str, level: str = "month") -> str:
        """Generalize date to month/year or just year"""
        try:
            date = datetime.fromisoformat(date_str)
            if level == "year":
                return str(date.year)
            elif level == "month":
                return f"{date.year}-{date.month:02d}"
            elif level == "decade":
                decade = (date.year // 10) * 10
                return f"{decade}s"
            else:
                return date_str
        except:
            return date_str

    def generalize_age(self, age: int, bins: List[int] = None) -> str:
        """Generalize age into age ranges"""
        if bins is None:
            bins = [0, 18, 25, 35, 45, 55, 65, 75, 100]

        for i in range(len(bins) - 1):
            if bins[i] <= age < bins[i + 1]:
                return f"{bins[i]}-{bins[i+1]-1}"

        return f"{bins[-1]}+"

    def generalize_location(self, location: str, level: str = "city") -> str:
        """Generalize location to city, region, or country"""
        # This would use a geocoding database in practice
        # Simplified example
        location_levels = {
            "New York": {"city": "New York", "region": "Northeast", "country": "USA"},
            "Los Angeles": {"city": "Los Angeles", "region": "West", "country": "USA"},
            "Chicago": {"city": "Chicago", "region": "Midwest", "country": "USA"}
        }

        if location in location_levels:
            return location_levels[location].get(level, location)
        return location

    # ============================================
    # PERTURBATION TECHNIQUES
    # ============================================

    def perturb_numeric(self, value: float, percentage: float = 0.1) -> float:
        """Add random noise to numeric value"""
        noise = value * percentage * (random.random() * 2 - 1)
        return round(value + noise, 2)

    def perturb_date(self, date_str: str, days_range: int = 30) -> str:
        """Shift date by random number of days"""
        try:
            date = datetime.fromisoformat(date_str)
            shift = random.randint(-days_range, days_range)
            new_date = date + timedelta(days=shift)
            return new_date.isoformat()
        except:
            return date_str

    # ============================================
    # COMPLETE ANONYMIZATION PIPELINE
    # ============================================

    def anonymize_record(self, record: Dict, rules: Dict[str, str]) -> Dict:
        """Apply multiple anonymization rules to a record"""
        anonymized = record.copy()

        for field, rule in rules.items():
            if field in anonymized:
                value = anonymized[field]

                if rule == 'mask_email':
                    anonymized[field] = self.mask_email(value)
                elif rule == 'mask_phone':
                    anonymized[field] = self.mask_phone(value)
                elif rule == 'mask_name':
                    anonymized[field] = self.mask_name(value)
                elif rule == 'mask_credit_card':
                    anonymized[field] = self.mask_credit_card(value)
                elif rule == 'substitute_email':
                    anonymized[field] = self.substitute_email()
                elif rule == 'substitute_name':
                    anonymized[field] = self.substitute_name()
                elif rule == 'substitute_phone':
                    anonymized[field] = self.substitute_phone()
                elif rule == 'substitute_address':
                    anonymized[field] = self.substitute_address()
                elif rule == 'tokenize':
                    anonymized[field] = self.tokenize(value, field)
                elif rule == 'generalize_date':
                    anonymized[field] = self.generalize_date(value, 'month')
                elif rule == 'generalize_age':
                    anonymized[field] = self.generalize_age(value)
                elif rule == 'perturb_numeric':
                    anonymized[field] = self.perturb_numeric(value)

        return anonymized

    def anonymize_dataset(self, dataset: List[Dict], rules: Dict[str, str]) -> List[Dict]:
        """Anonymize an entire dataset"""
        return [self.anonymize_record(record, rules) for record in dataset]


